@ToString(exclude = "password") // wyklucza wybrane pole (dane wrazliwe)
class User {
    private String username;
    private String password;
}

@ToString(of = {"username", "email"}) // odwrotnie: TYLKO wskazane pola (biala lista)
class Account {
    private String username;
    private String email;
    private String internalToken;
}

