// BLAD: @Data na podklasie ignoruje pola nadklasy w equals/hashCode/toString
class Employee {
    protected Long employeeId;
}

@Data
class Manager extends Employee {
    private String department;
}

Manager m1 = new Manager(); m1.setEmployeeId(1L); m1.setDepartment("IT");
Manager m2 = new Manager(); m2.setEmployeeId(2L); m2.setDepartment("IT");
System.out.println(m1.equals(m2)); // true! employeeId zignorowany

// POPRAWNIE: callSuper=true uwzglednia pola nadklasy
class Employee {
    protected Long employeeId;
}

@Getter @Setter
@ToString(callSuper = true)
@EqualsAndHashCode(callSuper = true)
class Manager extends Employee {
    private String department;
}

Manager m1 = new Manager(); m1.setEmployeeId(1L); m1.setDepartment("IT");
Manager m2 = new Manager(); m2.setEmployeeId(2L); m2.setDepartment("IT");
System.out.println(m1.equals(m2)); // false - employeeId TERAZ ma znaczenie
